export const CATEGORIES: Array<{ name: string; count: number }> = (() => {
  const counts = new Map<string, number>();
  for (const s of STYLES) counts.set(s.cat, (counts.get(s.cat) ?? 0) + 1);
  return [...counts.entries()].map(([name, count]) => ({ name, count }));
})();
